/**
 * 首页 banner：2 张不带平台名称的默认占位图轮播（走查 row2-3）。
 * 纯渐变色块占位，点击不跳转。数据在本文件内本地维护。
 */
const banners = ref([
  { id: 'b1', style: 'linear-gradient(135deg,#004fd0,#0a72ff)' },
  { id: 'b2', style: 'linear-gradient(135deg,#0f9e6e,#26b57f)' },
])
const bannerIndex = ref(0)

/* banner 轮播（走查 row2-3）：2 张占位图，高度沿用 .banner 的 min-height */
.banner-swiper { height: 112px; border-radius: 12px; overflow: hidden; }
.banner-slide { min-height: 112px; height: 112px; }
